  ('grovbase-shot-spec:wyniki-testow:czapka-z-lampka-led', 'Wyniki testów', 182, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Czapka z lampką LED', 'Produkt: Czapka z lampką LED; Kategoria: outdoor; Rundy: 1 + 2 ponowne; Wynik: gotowy zestaw; Główna lekcja: błędy losowe znikają po ponownej generacji bez zmian'),
  ('grovbase-shot-spec:wyniki-testow:drapak-dla-kota', 'Wyniki testów', 183, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Drapak dla kota', 'Produkt: Drapak dla kota; Kategoria: zwierzęta; Rundy: 3; Wynik: bardzo dobre; Główna lekcja: miękkie światło, zwierzę bohaterem, zbliżenie zawsze z całością'),
  ('grovbase-shot-spec:wyniki-testow:auto-rc', 'Wyniki testów', 184, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Auto RC', 'Produkt: Auto RC; Kategoria: outdoor; Rundy: 1; Wynik: gotowy zestaw; Główna lekcja: plan i prompty w całości od silnika'),
  ('grovbase-shot-spec:wyniki-testow:szczoteczka-soniczna', 'Wyniki testów', 185, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Szczoteczka soniczna', 'Produkt: Szczoteczka soniczna; Kategoria: beauty; Rundy: 3; Wynik: gotowy zestaw; Główna lekcja: różnorodność kadrów; chwyt opisany wprost; skóra zdrowa, nie „z porami”'),
  ('grovbase-shot-spec:wyniki-testow:pierwsze-rundy-szafki-i-szczoteczki-byly-naj', 'Wyniki testów', 186, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Pierwsze rundy szafki i szczoteczki były najsłabsze z całej…', 'Pierwsze rundy szafki i szczoteczki były najsłabsze z całej serii. W obu przypadkach model składał produkt z fragmentów, więc reguły o stanach produktu i zdjęciu całości są kluczowe dla produktów o złożonej budowie.'),
  ('grovbase-shot-spec:wyniki-testow:pierwszy-test-wedlug-tego-dokumentu-prostown', 'Wyniki testów', 187, date '2026-10-27', 'errors', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Pierwszy test według tego dokumentu (prostownica BaByliss PRO, 4…', 'Pierwszy test według tego dokumentu (prostownica BaByliss PRO, 4 zdjęcia, 3 referencje): chrom, chwyt, różnorodność kadrów i spójny styl zadziałały za pierwszym razem. Błędy: logo na szczotce, brak odbić w lustrze w salonie, uproszczone kręcenie loka.'),
  ('grovbase-shot-spec:wyniki-testow:pierwszy-test-z-kierunkami-kreatywnymi-worek', 'Wyniki testów', 188, date '2026-10-27', 'prompt_build', array['plan', 'prompt']::text[], 'global', '{}'::text[], 'knowledge', false, 'Pierwszy test z kierunkami kreatywnymi (worek do prania butów…', 'Pierwszy test z kierunkami kreatywnymi (worek do prania butów, 10 ujęć, 7 referencji): wszystkie 10 zaakceptowane za pierwszym razem. Kolejność promptu „moment i emocja → światło → kadr → produkt → scenografia” oraz przed i po w jednym kadrze dają poziom kampanii marek. Do pilnowania: ciepłe światło przesuwa szarą mikrofibrę w beż, a referencja z błędnym kolorem detalu (miętowy zamek na zdjęciu z pralką) przenosi błąd do sceny.'),
  ('grovbase-shot-spec:wyniki-testow:maska-lakiernicza-29-10-po-3-rundach-gotowy', 'Wyniki testów', 189, date '2026-10-29', 'creative', array['plan', 'prompt']::text[], 'recipe', array['industrial_cinematic']::text[], 'knowledge', false, 'Maska lakiernicza (29.10): po 3 rundach gotowy zestaw. Zadziałało…', 'Maska lakiernicza (29.10): po 3 rundach gotowy zestaw. Zadziałało połączenie: przepis „kinowy przemysłowy” dla ujęć detali (ciemny warsztat, kontra, mgiełka), styl reportażowy dla ujęć użycia (niski kąt, profil, kurz i mgiełka w kontrze) oraz detale ze zdjęć sprzedawcy kopiowane 1:1 z nową scenerią. Ujęcia użycia w różnych miejscach (warsztat, sad, budowa, przystań) pokazują szerokość zastosowań.'),
  ('grovbase-shot-spec:otwarte-kwestie-i-nastepne-k:najwieksze-nieznane-ryzyko-to-zdjecia-z-tele', 'Otwarte kwestie i następne kroki', 190, date '2026-10-27', 'context', '{}'::text[], 'global', '{}'::text[], 'reference', false, 'Największe nieznane ryzyko to zdjęcia z telefonu: wszystkie testy…', 'Największe nieznane ryzyko to zdjęcia z telefonu: wszystkie testy szły na profesjonalnych zdjęciach lub renderach producenta.'),
